R["cppa5-constexpr-parse"] = "#include <cstddef>\n#include <string>\n#include <string_view>\n\n// Parse \"name:value;name2:value2\" into the output at COMPILE time,\n// recording the entries into the provided fixed storage.\n// Return the number of entries parsed.\nconstexpr std::size_t parseSpec(std::string_view spec,\n                                std::string_view names[],\n                                int values[],\n                                std::size_t maxEntries);\n\nconstexpr std::size_t parseSpec(std::string_view spec, std::string_view names[], int values[], std::size_t maxEntries) {\n    std::size_t count = 0, pos = 0;\n    while (pos < spec.size() && count < maxEntries) {\n        while (pos < spec.size() && spec[pos] == ' ') ++pos;\n        std::size_t semi = pos;\n        while (semi < spec.size() && spec[semi] != ';') ++semi;\n        std::size_t colon = pos;\n        while (colon < semi && spec[colon] != ':') ++colon;\n        if (colon == semi) break;\n        std::size_t e = colon;\n        while (e > pos && spec[e-1] == ' ') --e;\n        std::size_t s2 = pos;\n        while (s2 < e && spec[s2] == ' ') ++s2;\n        names[count] = spec.substr(s2, e - s2);\n        std::size_t vstart = colon + 1;\n        while (vstart < semi && spec[vstart] == ' ') ++vstart;\n        int val = 0;\n        for (std::size_t i = vstart; i < semi; ++i) {\n            char c = spec[i];\n            if (c >= '0' && c <= '9') val = val * 10 + (c - '0');\n        }\n        values[count] = val;\n        ++count;\n        pos = semi + 1;\n    }\n    return count;\n}\n";
W["cppa5-constexpr-parse"] = "#include <cstddef>\n#include <string>\n#include <string_view>\n\n// Parse \"name:value;name2:value2\" into the output at COMPILE time,\n// recording the entries into the provided fixed storage.\n// Return the number of entries parsed.\nconstexpr std::size_t parseSpec(std::string_view spec,\n                                std::string_view names[],\n                                int values[],\n                                std::size_t maxEntries);\n\nconstexpr std::size_t parseSpec(std::string_view spec, std::string_view names[], int values[], std::size_t maxEntries) {\n    std::size_t count = 0, pos = 0;\n    while (pos < spec.size() && count < maxEntries) {\n        std::size_t semi = pos;\n        while (semi < spec.size() && spec[semi] != ';') ++semi;\n        std::size_t colon = pos;\n        while (colon < semi && spec[colon] != ':') ++colon;\n        if (colon == semi) break;\n        names[count] = spec.substr(pos, colon - pos);   // WRONG: no trim of spaces\n        int val = 0;\n        for (std::size_t i = colon + 1; i < semi; ++i) val = val * 10 + (spec[i] - '0');  // WRONG: includes spaces -> garbage\n        values[count] = val;\n        ++count;\n        pos = semi + 1;\n    }\n    return count;\n}\n";
