R["cppa8-atomic-hammer"] = "#include <atomic>\n#include <cstddef>\n#include <thread>\n#include <vector>\n\n// Increment the counter from n threads, incs times each.\nvoid hammer(std::atomic<int>& counter, int nThreads, int incs);\n\nvoid hammer(std::atomic<int>& counter, int nThreads, int incs) {\n    std::vector<std::thread> ts;\n    for (int t = 0; t < nThreads; ++t) {\n        ts.emplace_back([&counter, incs] {\n            for (int i = 0; i < incs; ++i) counter.fetch_add(1, std::memory_order_relaxed);\n        });\n    }\n    for (auto& t : ts) t.join();\n}\n";
