R["cppa8-memmodel-checkpoint"] = "#include <atomic>\n\n// A histogram cell with a lock-free bump and a reset that publishes.\nstruct Cell {\n    std::atomic<unsigned> count{0};\n    std::atomic<bool> fresh{false};\n    int stamp = 0;   // ordinary int, ordered via fresh\n\n    void bump();                       // +1, relaxed\n    unsigned total() const;            // current count\n    void reset(int newStamp);          // zero the count, then publish the stamp\n    int readStamped();                 // acquire; returns -1 until a reset published\n};\n\nvoid Cell::bump() { count.fetch_add(1, std::memory_order_relaxed); }\nunsigned Cell::total() const { return count.load(std::memory_order_relaxed); }\nvoid Cell::reset(int newStamp) {\n    count.store(0, std::memory_order_relaxed);\n    stamp = newStamp;\n    fresh.store(true, std::memory_order_release);\n}\nint Cell::readStamped() {\n    if (!fresh.load(std::memory_order_acquire)) return -1;\n    return stamp;\n}\n";
W["cppa8-memmodel-checkpoint"] = "#include <atomic>\n\n// A histogram cell with a lock-free bump and a reset that publishes.\nstruct Cell {\n    std::atomic<unsigned> count{0};\n    std::atomic<bool> fresh{false};\n    int stamp = 0;   // ordinary int, ordered via fresh\n\n    void bump();                       // +1, relaxed\n    unsigned total() const;            // current count\n    void reset(int newStamp);          // zero the count, then publish the stamp\n    int readStamped();                 // acquire; returns -1 until a reset published\n};\n\nvoid Cell::bump() { count.fetch_add(1, std::memory_order_relaxed); }\nunsigned Cell::total() const { return count.load(std::memory_order_relaxed); }\nvoid Cell::reset(int newStamp) {\n    stamp = newStamp;\n    fresh.store(true, std::memory_order_release);  // WRONG: count never zeroed\n}\nint Cell::readStamped() {\n    if (!fresh.load(std::memory_order_acquire)) return -1;\n    return stamp;\n}\n";
R["cppa9-parallel-sum"] = "#include <atomic>\n#include <numeric>\n#include <thread>\n#include <vector>\n\n// Sum [0, n) using nThreads threads splitting the range evenly.\nlong long parallelSum(int n, int nThreads);\n\nlong long parallelSum(int n, int nThreads) {\n    std::atomic<long long> total{0};\n    std::vector<std::thread> ts;\n    for (int i = 0; i < nThreads; ++i) {\n        int lo = (int)((long long)i * n / nThreads);\n        int hi = (int)((long long)(i + 1) * n / nThreads);\n        ts.emplace_back([lo, hi, &total] {\n            long long s = 0;\n            for (int x = lo; x < hi; ++x) s += x;\n            total.fetch_add(s, std::memory_order_relaxed);\n        });\n    }\n    for (auto& t : ts) t.join();\n    return total.load();\n}\n";
