R["cppa9-concurrency-checkpoint"] = "#include <condition_variable>\n#include <deque>\n#include <mutex>\n#include <optional>\n#include <thread>\n\n// A worker that moves values from inbox to outbox, transformed by +delta,\n// until the inbox closes (sentinel -1 means close).\nclass Stage {\npublic:\n    Stage(int delta);\n    void put(int v);       // inbox push (sentinel -1 closes)\n    int take();            // outbox pop (blocks)\n    void run();            // the worker loop (called on its own thread by tests)\nprivate:\n    int delta_;\n    std::deque<int> in_;                  // inbox queue\n    std::deque<int> out_;                 // outbox queue\n    std::mutex m_;                        // guards in_\n    std::mutex om_;                       // guards out_\n    std::condition_variable inCv_;        // signaled when in_ becomes non-empty\n    std::condition_variable oCv_;         // signaled when out_ becomes non-empty\n};\n\nStage::Stage(int delta) : delta_(delta) {}\nvoid Stage::put(int v) {\n    { std::lock_guard<std::mutex> lk(m_); in_.push_back(v); } inCv_.notify_one();\n}\nint Stage::take() {\n    std::unique_lock<std::mutex> lk(om_);\n    oCv_.wait(lk, [this] { return !out_.empty(); });\n    int v = out_.front();\n    out_.pop_front();\n    return v;\n}\nvoid Stage::run() {\n    while (true) {\n        int v;\n        { std::unique_lock<std::mutex> lk(m_); inCv_.wait(lk, [this]{ return !in_.empty(); }); v = in_.front(); in_.pop_front(); }\n        if (v == -1) break;\n        { std::lock_guard<std::mutex> lk(om_); out_.push_back(v + delta_); } oCv_.notify_one();\n    }\n}\n";
W["cppa9-concurrency-checkpoint"] = "#include <condition_variable>\n#include <deque>\n#include <mutex>\n#include <optional>\n#include <thread>\n\n// A worker that moves values from inbox to outbox, transformed by +delta,\n// until the inbox closes (sentinel -1 means close).\nclass Stage {\npublic:\n    Stage(int delta);\n    void put(int v);       // inbox push (sentinel -1 closes)\n    int take();            // outbox pop (blocks)\n    void run();            // the worker loop (called on its own thread by tests)\nprivate:\n    int delta_;\n    std::deque<int> in_;                  // inbox queue\n    std::deque<int> out_;                 // outbox queue\n    std::mutex m_;                        // guards in_\n    std::mutex om_;                       // guards out_\n    std::condition_variable inCv_;        // signaled when in_ becomes non-empty\n    std::condition_variable oCv_;         // signaled when out_ becomes non-empty\n};\n\nvoid Stage::put(int v) {\n    if (v == -1) { return; }  // WRONG: bypasses the inbox entirely\n    { std::lock_guard<std::mutex> lk(om_); out_.push_back(v); }  // WRONG: raw value straight to the outbox\n    oCv_.notify_one();\n}\nint Stage::take() {\n    std::unique_lock<std::mutex> lk(om_);\n    oCv_.wait(lk, [this] { return !out_.empty(); });\n    int v = out_.front();\n    out_.pop_front();\n    return v;\n}\nvoid Stage::run() {\n    while (true) {\n        int v;\n        { std::unique_lock<std::mutex> lk(m_); inCv_.wait(lk, [this]{ return !in_.empty(); }); v = in_.front(); in_.pop_front(); }\n        if (v == -1) break;\n        { std::lock_guard<std::mutex> lk(om_); out_.push_back(v + delta_); } oCv_.notify_one();\n    }\n}\n";
R["cppa10-alloc-checkpoint"] = "#include <cstddef>\n#include <cstdint>\n#include <vector>\n\n// Deterministic allocation tracker the tests drive.\n// (No real heap calls: the challenge models allocation behavior.)\nclass AllocTracker {\npublic:\n    static int& allocs()   { static int n = 0; return n; }\n    static int& frees()    { static int n = 0; return n; }\n    static int& live()     { static int n = 0; return n; }\n    static void noteAlloc(){ ++allocs(); ++live(); }\n    static void noteFree() { ++frees(); --live(); }\n    static void reset()    { allocs() = frees() = live() = 0; }\n};\n\n// A fixed-size pool of 'blocks' blocks of 'blockSize' bytes.\n// acquire() returns a byte pointer or nullptr when exhausted;\n// release(p) returns the block to the pool (p must be from this pool).\nclass BytePool {\npublic:\n    BytePool(std::size_t blocks, std::size_t blockSize);\n    ~BytePool();\n    std::uint8_t* acquire();          // AllocTracker::noteAlloc() on success\n    void release(std::uint8_t* p);    // AllocTracker::noteFree() on success\n    std::size_t available() const;\nprivate:\n    std::size_t blocks_, blockSize_;\n    std::uint8_t* storage_ = nullptr;   // your bookkeeping here\n    std::vector<std::uint8_t*> freeList_;\n};\n\nBytePool::BytePool(std::size_t blocks, std::size_t blockSize) : blocks_(blocks), blockSize_(blockSize) {\n    storage_ = new std::uint8_t[blocks * blockSize];\n    for (std::size_t i = 0; i < blocks; ++i) freeList_.push_back(storage_ + i * blockSize);\n}\nBytePool::~BytePool() { delete[] storage_; }\nstd::uint8_t* BytePool::acquire() {\n    if (freeList_.empty()) return nullptr;\n    std::uint8_t* p = freeList_.back();\n    freeList_.pop_back();\n    AllocTracker::noteAlloc();\n    return p;\n}\nvoid BytePool::release(std::uint8_t* p) { AllocTracker::noteFree(); freeList_.push_back(p); }\nstd::size_t BytePool::available() const { return freeList_.size(); }\n";
W["cppa10-alloc-checkpoint"] = "#include <cstddef>\n#include <cstdint>\n#include <vector>\n\n// Deterministic allocation tracker the tests drive.\n// (No real heap calls: the challenge models allocation behavior.)\nclass AllocTracker {\npublic:\n    static int& allocs()   { static int n = 0; return n; }\n    static int& frees()    { static int n = 0; return n; }\n    static int& live()     { static int n = 0; return n; }\n    static void noteAlloc(){ ++allocs(); ++live(); }\n    static void noteFree() { ++frees(); --live(); }\n    static void reset()    { allocs() = frees() = live() = 0; }\n};\n\n// A fixed-size pool of 'blocks' blocks of 'blockSize' bytes.\n// acquire() returns a byte pointer or nullptr when exhausted;\n// release(p) returns the block to the pool (p must be from this pool).\nclass BytePool {\npublic:\n    BytePool(std::size_t blocks, std::size_t blockSize);\n    ~BytePool();\n    std::uint8_t* acquire();          // AllocTracker::noteAlloc() on success\n    void release(std::uint8_t* p);    // AllocTracker::noteFree() on success\n    std::size_t available() const;\nprivate:\n    std::size_t blocks_, blockSize_;\n    std::uint8_t* storage_ = nullptr;   // your bookkeeping here\n    std::vector<std::uint8_t*> freeList_;\n};\n\nBytePool::BytePool(std::size_t blocks, std::size_t blockSize) : blocks_(blocks), blockSize_(blockSize) {\n    storage_ = new std::uint8_t[blocks * blockSize];\n    for (std::size_t i = 0; i < blocks; ++i) freeList_.push_back(storage_ + i * blockSize);\n}\nBytePool::~BytePool() { delete[] storage_; }\nstd::uint8_t* BytePool::acquire() {\n    if (freeList_.empty()) return nullptr;\n    std::uint8_t* p = freeList_.back();\n    freeList_.pop_back();\n    AllocTracker::noteAlloc();\n    return p;\n}\nvoid BytePool::release(std::uint8_t* p) { AllocTracker::noteFree(); }  // WRONG: block never returned to the free list\nstd::size_t BytePool::available() const { return freeList_.size(); }\n";
R["cppa11-perf-checkpoint"] = "#include <cstdint>\n#include <cstdlib>\n#include <vector>\n\n// Allocation counter (each graded test is its own program).\ninline int& gAllocs() { static int n = 0; return n; }\nvoid* operator new(std::size_t sz) { ++gAllocs(); return std::malloc(sz); }\nvoid* operator new[](std::size_t sz) { ++gAllocs(); return std::malloc(sz); }\nvoid operator delete(void* p) noexcept { std::free(p); }\nvoid operator delete[](void* p) noexcept { std::free(p); }\nvoid operator delete(void* p, std::size_t) noexcept { std::free(p); }\nvoid operator delete[](void* p, std::size_t) noexcept { std::free(p); }\ninline int allocCount() { return gAllocs(); }\n\n// Comparison-counted element (see module 11 practice).\n#include <unordered_set>\n\nstruct Tracked {\n    long long value;\n    inline static int& comparisons() { static int n = 0; return n; }\n    friend bool operator<(const Tracked& a, const Tracked& b) { ++comparisons(); return a.value < b.value; }\n    friend bool operator==(const Tracked& a, const Tracked& b) { ++comparisons(); return a.value == b.value; }\n};\ntemplate <>\nstruct std::hash<Tracked> {\n    std::size_t operator()(const Tracked& t) const noexcept { return std::hash<long long>{}(t.value); }\n};\ninline int trackedComparisons() { return Tracked::comparisons(); }\n\n// (1) out gets 0..n-1 with at most one allocation.\nvoid buildRange(std::vector<int>& out, int n);\n\n// (2) number of distinct values; hash-based membership keeps comparisons <= n.\nint countDistinct(const std::vector<Tracked>& data);\nvoid buildRange(std::vector<int>& out, int n) {\n    out.reserve(n);\n    for (int i = 0; i < n; ++i) out.push_back(i);\n}\nint countDistinct(const std::vector<Tracked>& data) {\n    std::unordered_set<Tracked> s;\n    for (const Tracked& t : data) s.insert(t);\n    return static_cast<int>(s.size());\n}\n";
W["cppa11-perf-checkpoint"] = "#include <cstdint>\n#include <cstdlib>\n#include <vector>\n\n// Allocation counter (each graded test is its own program).\ninline int& gAllocs() { static int n = 0; return n; }\nvoid* operator new(std::size_t sz) { ++gAllocs(); return std::malloc(sz); }\nvoid* operator new[](std::size_t sz) { ++gAllocs(); return std::malloc(sz); }\nvoid operator delete(void* p) noexcept { std::free(p); }\nvoid operator delete[](void* p) noexcept { std::free(p); }\nvoid operator delete(void* p, std::size_t) noexcept { std::free(p); }\nvoid operator delete[](void* p, std::size_t) noexcept { std::free(p); }\ninline int allocCount() { return gAllocs(); }\n\n// Comparison-counted element (see module 11 practice).\n#include <unordered_set>\n\nstruct Tracked {\n    long long value;\n    inline static int& comparisons() { static int n = 0; return n; }\n    friend bool operator<(const Tracked& a, const Tracked& b) { ++comparisons(); return a.value < b.value; }\n    friend bool operator==(const Tracked& a, const Tracked& b) { ++comparisons(); return a.value == b.value; }\n};\ntemplate <>\nstruct std::hash<Tracked> {\n    std::size_t operator()(const Tracked& t) const noexcept { return std::hash<long long>{}(t.value); }\n};\ninline int trackedComparisons() { return Tracked::comparisons(); }\n\n// (1) out gets 0..n-1 with at most one allocation.\nvoid buildRange(std::vector<int>& out, int n);\n\n// (2) number of distinct values; hash-based membership keeps comparisons <= n.\nint countDistinct(const std::vector<Tracked>& data);\nvoid buildRange(std::vector<int>& out, int n) {\n    for (int i = 0; i < n; ++i) out.push_back(i);   // WRONG: no reserve\n}\nint countDistinct(const std::vector<Tracked>& data) {\n    std::vector<Tracked> v = data;                  // WRONG: sort-based -> comparisons blow the bound\n    std::sort(v.begin(), v.end());\n    v.erase(std::unique(v.begin(), v.end()), v.end());\n    return static_cast<int>(v.size());\n}\n";
