R["cppa12-ub-checkpoint"] = "#include <climits>\n#include <cstdint>\n#include <optional>\n#include <string>\n#include <vector>\n\n// The defensive battery: every operation either returns its defined result\n// or std::nullopt when the operation would be undefined/unsafe.\nstd::optional<int> addChecked(int a, int b);\nstd::optional<int> mulChecked(int a, int b);\nstd::optional<int> atChecked(const std::vector<int>& v, std::size_t i);\nstd::optional<int> divChecked(int a, int b);\n\nstd::optional<int> addChecked(int a, int b) {\n    if (b > 0 && a > INT_MAX - b) return std::nullopt;\n    if (b < 0 && a < INT_MIN - b) return std::nullopt;\n    return a + b;\n}\nstd::optional<int> mulChecked(int a, int b) {\n    if (a == 0 || b == 0) return 0;\n    if (a == -1 && b == INT_MIN) return std::nullopt;\n    if (b == -1 && a == INT_MIN) return std::nullopt;\n    long long r = static_cast<long long>(a) * b;\n    if (r > INT_MAX || r < INT_MIN) return std::nullopt;\n    return static_cast<int>(r);\n}\nstd::optional<int> atChecked(const std::vector<int>& v, std::size_t i) {\n    if (i >= v.size()) return std::nullopt;\n    return v[i];\n}\nstd::optional<int> divChecked(int a, int b) {\n    if (b == 0) return std::nullopt;\n    if (a == INT_MIN && b == -1) return std::nullopt;\n    return a / b;\n}\n";
