R["cppa19-token-bucket"] = "#include <algorithm>\n#include <cstdint>\n#include <map>\n#include <functional>\n#include <optional>\n#include <string>\n#include <vector>\n\n// --- deterministic time seam ---\nstruct Clock {\n    virtual ~Clock() = default;\n    virtual std::int64_t nowMs() const = 0;\n};\nstruct FixedClock : Clock {                 // test double\n    explicit FixedClock(std::int64_t t) : t_(t) {}\n    std::int64_t nowMs() const override { return t_; }\n    void advance(std::int64_t ms) { t_ += ms; }\nprivate:\n    std::int64_t t_;\n};\n\n// --- token bucket over the seam ---\nstruct TokenBucket {\n    TokenBucket(const Clock* clock, std::int64_t capacity, std::int64_t refillPerSec);\n    // true and consumes one token if allowed; false otherwise.\n    bool tryConsume();\n    std::int64_t tokens() const;\n\nprivate:\n    const Clock* clock_;\n    std::int64_t capacity_;\n    std::int64_t refillPerSec_;   // tokens per second\n    double tokens_ = 0.0;\n    std::int64_t lastMs_ = 0;\n};\n\n// --- sync event bus, registration-order dispatch ---\nstruct EventBus {\n    using Handler = std::function<void(const std::string&)>;\n\n    int subscribe(Handler h);          // returns a subscription id\n    bool unsubscribe(int id);          // true if it existed\n    void emit(const std::string& event) const;   // calls handlers in subscription order\n\nprivate:\n    std::vector<std::pair<int, Handler>> handlers_;\n    int nextId_ = 1;\n};\n\n// --- configuration ladder: defaults < file < env < flag ---\nenum class Layer { Default, File, Env, Flag };\n\nstruct ConfigLadder {\n    void set(Layer l, const std::string& key, const std::string& value);\n    std::optional<std::string> get(const std::string& key) const;   // highest layer wins\n    std::optional<Layer> source(const std::string& key) const;      // which layer set it\n\nprivate:\n    std::map<std::string, std::pair<Layer, std::string>> entries_;\n};\nTokenBucket::TokenBucket(const Clock* clock, std::int64_t capacity, std::int64_t refillPerSec)\n    : clock_(clock), capacity_(capacity), refillPerSec_(refillPerSec), tokens_(double(capacity)), lastMs_(clock->nowMs()) {}\nbool TokenBucket::tryConsume() {\n    const std::int64_t now = clock_->nowMs();\n    tokens_ = std::min(double(capacity_), tokens_ + (now - lastMs_) / 1000.0 * refillPerSec_);\n    lastMs_ = now;\n    if (tokens_ >= 1.0) { tokens_ -= 1.0; return true; }\n    return false;\n}\nstd::int64_t TokenBucket::tokens() const { return std::int64_t(tokens_); }\nint EventBus::subscribe(Handler h) { int id = nextId_++; handlers_.emplace_back(id, std::move(h)); return id; }\nbool EventBus::unsubscribe(int id) {\n    for (auto it = handlers_.begin(); it != handlers_.end(); ++it)\n        if (it->first == id) { handlers_.erase(it); return true; }\n    return false;\n}\nvoid EventBus::emit(const std::string& event) const {\n    auto snapshot = handlers_;\n    for (auto& [id, h] : snapshot) {\n        auto it = std::find_if(handlers_.begin(), handlers_.end(),\n                               [id](const auto& p) { return p.first == id; });\n        if (it != handlers_.end()) h(event);\n    }\n}\nvoid ConfigLadder::set(Layer l, const std::string& key, const std::string& value) {\n    auto it = entries_.find(key);\n    if (it == entries_.end() || int(l) >= int(it->second.first))\n        entries_[key] = {l, value};\n}\nstd::optional<std::string> ConfigLadder::get(const std::string& key) const {\n    auto it = entries_.find(key);\n    if (it == entries_.end()) return std::nullopt;\n    return it->second.second;\n}\nstd::optional<Layer> ConfigLadder::source(const std::string& key) const {\n    auto it = entries_.find(key);\n    if (it == entries_.end()) return std::nullopt;\n    return it->second.first;\n}";
